<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/cepfms_operational_helpers.php';requireCefPermission('cepfms.complaints.view');
$rows=db()->query("SELECT s.reference_number,s.title,s.created_at,s.status,c.name category_name,cp.affected_service,cp.urgency_level,cp.acknowledgement_target_at,cp.response_target_at,cp.resolution_target_at,cp.resolved_at,(SELECT COUNT(*) FROM cef_escalations e WHERE e.submission_id=s.id AND e.status='Open') escalations FROM cef_submissions s JOIN cef_complaints cp ON cp.submission_id=s.id LEFT JOIN cef_categories c ON c.id=s.category_id WHERE s.submission_type='Complaint' AND s.deleted_at IS NULL ORDER BY s.created_at DESC")->fetchAll();
$pageTitle='Complaint & Issue Report';$activeMenu='complaints';$extraCss=[appUrl('assets/css/cepfms-operational.css')];include __DIR__.'/../../layouts/header.php';
?>
<div class="app-wrapper"><?php include __DIR__.'/../../layouts/sidebar.php'; ?><main class="main-content"><div class="cef-head"><div><div class="cef-eyebrow">Operational Report</div><h1>Complaint & Issue Tracking Report</h1><p>Complaint service area, urgency, service-level targets, escalation count, resolution state and current status.</p></div><a class="btn btn-outline-secondary" href="index.php">Complaint Registry</a></div><div class="card cef-card"><div class="table-responsive"><table class="table cef-table mb-0"><thead><tr><th>Reference</th><th>Complaint</th><th>Service</th><th>Urgency</th><th>Ack Target</th><th>Response Target</th><th>Resolution Target</th><th>Escalations</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['reference_number']) ?></td><td><?= e($r['title']) ?><div class="small text-muted"><?= e($r['category_name']?:'Unclassified') ?></div></td><td><?= e($r['affected_service']?:'—') ?></td><td><?= e($r['urgency_level']) ?></td><td><?= formatDateTime($r['acknowledgement_target_at']) ?></td><td><?= formatDateTime($r['response_target_at']) ?></td><td><?= formatDateTime($r['resolution_target_at']) ?></td><td><?= (int)$r['escalations'] ?></td><td><?= e($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></main></div>
<?php include __DIR__.'/../../layouts/footer.php'; ?>
